const fs=require('node:fs'),assert=require('node:assert/strict');
const c=require('./lib/memoryEvalVnext/protocol/canonicalJson.ts');
const w=require('./lib/memoryEvalVnext/protocol/wire.ts');
const t=require('./lib/memoryEvalVnext/protocol/trust.ts');
const s=require('./lib/memoryEvalVnext/protocol/signatures.ts');
const pub=JSON.parse(fs.readFileSync('tests/fixtures/memory-eval-vnext/wire-vectors.json','utf8')).publicEd25519[0];
const blob={path:'fixtures/public.txt',byteLength:1,rawSha256:'a'.repeat(64)};
const p={schemaVersion:1,purpose:'s2_source_evidence',signerId:'importer-A',keyId:'a'.repeat(32),trustEpoch:'epoch-A',contentDigest:'b'.repeat(64),issuedAt:'2026-09-09T00:00:00Z'};
const a={trustEpoch:p.trustEpoch,signerId:p.signerId,keyId:p.keyId,publicKeyBase64:Buffer.from(pub.publicKeyHex,'hex').toString('base64'),roles:['importer'],validFrom:'2026-09-08T00:00:00Z',validUntil:null,revokedAt:null,registrationReceipt:blob,previousEpochDigest:null};
const ex=(p,a)=>({purpose:p.purpose,signerId:p.signerId,keyId:p.keyId,trustEpoch:p.trustEpoch,contentDigest:p.contentDigest,previousEpochDigest:a.previousEpochDigest});
const out=r=>r.ok?'ok':r.error;
const idInputs=['importer-A','@importer','!~','imp\n','imp\r','imp\t','imp\0',' ',' imp','imp ',String.fromCharCode(127),'é','e\u0301','imp\u2028','imp\u2029',''];
const idRows=idInputs.map(value=>{
  const payload={...p,signerId:value},anchor={...a,signerId:value};
  return {input:value,inputCodePoints:[...value].map(x=>x.codePointAt(0)),asciiPredicate:w.isAsciiId(value),payloadShape:out(w.checkWire('SignaturePayload',payload)),anchorShape:out(w.checkWire('TrustAnchor',anchor)),bindingAllEqual:out(t.compareTrustBinding(payload,anchor,ex(payload,anchor),p.issuedAt)),signatureMessage:out(s.signatureMessage(payload))};
});
const pathInputs=['fixtures/public.txt','한글/증거 파일.json','é/한.txt','e\u0301/x','a b',' a ',' ','a\nb','a\rb','a\tb','a\0b','a'+String.fromCharCode(127)+'b','a\u0085b','a\u2028b','a\u2029b','a\u200bb','a\u202eb','a/../b','a//b','./a','/a','a/','C:/a','C:a','dir/C:a','a\\b','a/..x','a/%2e%2e/b','CON','a.',''];
const pathRows=pathInputs.map(value=>({input:value,inputCodePoints:[...value].map(x=>x.codePointAt(0)),canonical:out(c.encodeCanonical(value)),blobShape:out(w.checkWire('BlobRef',{...blob,path:value})),gitShape:out(w.checkWire('GitFileRef',{commit:'d'.repeat(40),path:value,rawSha256:blob.rawSha256})),nestedAnchor:out(w.checkWire('TrustAnchor',{...a,registrationReceipt:{...blob,path:value}}))}));
const asciiSweep=Array.from({length:128},(_,x)=>{const input=String.fromCharCode(x);return {codePoint:x,id:w.isAsciiId(input),path:out(w.checkWire('BlobRef',{...blob,path:'a'+input+'b'}))};});
const serialStrings=['imp\n','a\tb',String.fromCharCode(127)].map(input=>({input,canonicalHex:Buffer.from(c.encodeCanonical(input).value).toString('hex')}));
const comparisons={
  signerCaseDifference:out(t.compareTrustBinding({...p,signerId:'Importer-A'},a,ex(p,a),p.issuedAt)),
  signerLfOnlyExpected:out(t.compareTrustBinding(p,a,{...ex(p,a),signerId:'importer-A\n'},p.issuedAt)),
  epochSpaceAllEqual:out(t.compareTrustBinding({...p,trustEpoch:' '},{...a,trustEpoch:' '},{...ex(p,a),trustEpoch:' '},p.issuedAt)),
  unsupportedNfcPurpose:out(s.signatureMessage({...p,purpose:'unknown_purpose'})),
  c02ApproverAtShape:out(w.checkWire('SignaturePayload',{...p,purpose:'s2_activation_approval',signerId:'@user'})),
  c04ApproverAtBinding:out(t.compareTrustBinding({...p,purpose:'s2_activation_approval',signerId:'@user'},{...a,signerId:'@user',roles:['approver']},{...ex(p,a),purpose:'s2_activation_approval',signerId:'@user'},p.issuedAt))
};
console.log(JSON.stringify({at:new Date().toISOString(),idRows,pathRows,asciiSweep,serialStrings,comparisons,noKeyGenerationOrSigning:true,noNetworkOrDb:true}));
